contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedDrugs) public {
        c.seedMarket(seedDrugs);
        require(c.initialized());
        require(c.marketDrugs() == seedDrugs);
        c.getFreeKilo();
        uint256 kilos = c.getMyKilo();
        bool reverted;
        try c.getFreeKilo() { reverted = false; } catch { reverted = true; }
        assert(reverted && kilos == c.STARTING_KILOS());
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 seedDrugs) public payable {
        require(seedDrugs > 0);
        uint256 amount = msg.value;
        require(amount > 0);

        // initialize the market
        c.seedMarket(seedDrugs);

        // buy drugs with all the attached Ether
        c.buyDrugs{value: amount}();

        // all bought drugs are claimed; no kilos, so no production
        uint256 myDrugs = c.getMyDrugs();
        require(myDrugs > 0);

        uint256 before = address(this).balance;

        // sell everything back
        c.sellDrugs();

        uint256 after_ = address(this).balance;

        // proceeds must be positive (drugs have value) but strictly less
        // than the amount spent: the fee/spread guarantees the player loses
        assert(after_ > before && after_ - before < amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 seedDrugs, uint256 amount) public payable {
        require(seedDrugs > 0);
        require(amount > 0);
        require(address(this).balance >= amount);

        // initialize the market
        c.seedMarket(seedDrugs);

        // buyer has no kilos and no claimed drugs yet
        require(c.Kilos(address(this)) == 0);
        uint256 claimedBefore = c.claimedDrugs(address(this));
        uint256 balBefore = address(c).balance;
        require(balBefore >= amount);

        // expected purchase price uses the post-fee contract balance
        uint256 expected = c.calculateDrugBuy(amount, balBefore - amount);
        uint256 fee = c.devFee(expected);

        c.buyDrugs{value: amount}();

        // since Kilos == 0, getMyDrugs() equals claimedDrugs only
        uint256 myDrugs = c.getMyDrugs();

        // the buyer receives exactly 96% of the quoted trade (4% dev fee),
        // and nothing is lost or gained elsewhere
        assert(expected >= fee && myDrugs == claimedBefore + (expected - fee));
    }

    receive() external payable {}
}

