contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.seedMarket(1000);
        uint256 kilosBefore = c.getMyKilo();
        uint256 drugsBefore = c.getMyDrugs();
        uint256 balBefore = address(c).balance;
        uint256 expected = c.calculateDrugBuy(amount, balBefore - amount);
        uint256 fee = c.devFee(expected);
        c.buyDrugs{value: amount}();
        uint256 drugsAfter = c.getMyDrugs();
        assert(drugsAfter == drugsBefore + (expected - fee) && c.getMyKilo() == kilosBefore);
    }
    receive() external payable {}
}
